/**
 * Milestone lifecycle: create, rename, close (re-homing open issues), reopen and the progress-bearing reads.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import {
  isMilestoneOpen,
  isMilestoneOverdue,
  MilestoneStateError,
  normalizeMilestoneName,
} from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneWithProgress } from "@/types/milestone";
import type { Project } from "@/types/project";

async function loadProject(orgId: OrgId, projectId: ProjectId): Promise<Project> {
  return requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
}

async function loadMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  return requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
}

function assertNameFree(
  siblings: readonly Milestone[],
  name: string,
  exceptId: MilestoneId | null,
): void {
  const key = normalizeMilestoneName(name);
  if (
    siblings.some(
      (m) => m.id !== exceptId && normalizeMilestoneName(m.name) === key,
    )
  ) {
    throw new MilestoneStateError("name_taken", `Milestone name "${name}" is taken`);
  }
}

function assertRoomForOpen(siblings: readonly Milestone[]): void {
  if (siblings.filter(isMilestoneOpen).length >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError(
      "too_many_open",
      `A project holds at most ${MAX_OPEN_MILESTONES_PER_PROJECT} open milestones`,
    );
  }
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = await loadProject(input.orgId, input.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const siblings = await milestoneRepo.listProjectMilestones(
    input.orgId,
    project.id,
  );
  assertNameFree(siblings, input.name, null);
  assertRoomForOpen(siblings);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name: input.name,
    targetDate: input.targetDate,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const milestone = await loadMilestone(input.orgId, input.milestoneId);
  const project = await loadProject(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (input.name !== undefined) {
    const siblings = await milestoneRepo.listProjectMilestones(
      input.orgId,
      project.id,
    );
    assertNameFree(siblings, input.name, milestone.id);
  }

  return milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    name: input.name,
    targetDate: input.targetDate,
  });
}

export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const milestone = await loadMilestone(input.orgId, input.milestoneId);
  const project = await loadProject(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (!isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("closed", `Milestone ${milestone.id} is closed`);
  }

  if (input.moveOpenIssuesTo !== null) {
    if (input.moveOpenIssuesTo === milestone.id) {
      throw new NotFoundError("Milestone", input.moveOpenIssuesTo);
    }
    const target = await milestoneRepo.findMilestoneById(
      input.orgId,
      input.moveOpenIssuesTo,
    );
    if (target === null || target.projectId !== milestone.projectId) {
      throw new NotFoundError("Milestone", input.moveOpenIssuesTo);
    }
    if (!isMilestoneOpen(target)) {
      throw new MilestoneStateError("closed", `Milestone ${target.id} is closed`);
    }
  }

  const result = await milestoneRepo.closeMilestone(
    input.orgId,
    milestone.id,
    input.moveOpenIssuesTo,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
    movedToMilestoneId: input.moveOpenIssuesTo,
    movedIssueIds: result.movedIssueIds,
  });

  return result;
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (isMilestoneOpen(milestone)) {
    throw new MilestoneStateError(
      "already_open",
      `Milestone ${milestone.id} is already open`,
    );
  }

  const siblings = await milestoneRepo.listProjectMilestones(orgId, project.id);
  assertRoomForOpen(siblings);

  const reopened = await milestoneRepo.reopenMilestone(orgId, milestone.id);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/** Open first, then closed; earliest target first with undated last; oldest first on ties. */
function compareMilestones(a: Milestone, b: Milestone): number {
  const openDiff = Number(a.closedAt !== null) - Number(b.closedAt !== null);
  if (openDiff !== 0) return openDiff;
  if (a.targetDate !== b.targetDate) {
    if (a.targetDate === null) return 1;
    if (b.targetDate === null) return -1;
    const diff = Date.parse(a.targetDate) - Date.parse(b.targetDate);
    if (diff !== 0) return diff;
  }
  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = await loadProject(orgId, projectId);
  assertCan(actor, "project:read", projectResource(project));

  const now = new Date();
  const all = [...(await milestoneRepo.listProjectMilestones(orgId, projectId))];
  all.sort(compareMilestones);
  const progress = await milestoneRepo.progressByMilestone(
    orgId,
    all.map((m) => m.id),
  );

  return all.map((milestone) => {
    const p = progress.get(milestone.id) ?? { total: 0, open: 0, closed: 0 };
    return {
      milestone,
      progress: p,
      overdue: isMilestoneOverdue(milestone, p, now),
    };
  });
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = await loadMilestone(orgId, milestoneId);
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:read", projectResource(project));

  const progress = (
    await milestoneRepo.progressByMilestone(orgId, [milestone.id])
  ).get(milestone.id) ?? { total: 0, open: 0, closed: 0 };

  return {
    milestone,
    progress,
    overdue: isMilestoneOverdue(milestone, progress),
  };
}
