/**
 * Milestone rows and the issue counts that give them progress.
 */
import { and, asc, count, eq, inArray, isNull, notInArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toMilestone } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of a project, closed ones included, oldest first. */
export async function listProjectMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  return getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(asc(milestones.createdAt), asc(milestones.id))
    .all()
    .map(toMilestone);
}

export async function insertMilestone(input: {
  orgId: OrgId;
  projectId: ProjectId;
  name: string;
  targetDate: IsoTimestamp | null;
}): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: { name?: string; targetDate?: IsoTimestamp | null },
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.targetDate === undefined ? {} : { targetDate: patch.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();
  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

export async function reopenMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();
  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Closes the milestone and re-homes its open live issues in one transaction.
 * Returns the closed milestone and the ids of the issues that moved.
 */
export async function closeMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  moveTo: MilestoneId | null,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  const stamp = toIsoTimestamp(new Date());
  return getDb().transaction((tx) => {
    const openIssues = and(
      orgPredicate(issues.orgId, orgId),
      eq(issues.milestoneId, milestoneId),
      isNull(issues.archivedAt),
      notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
    );
    const moved = tx
      .select({ id: issues.id })
      .from(issues)
      .where(openIssues)
      .all()
      .map((r) => r.id as IssueId);

    if (moved.length > 0) {
      tx.update(issues)
        .set({ milestoneId: moveTo, updatedAt: stamp })
        .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, moved)))
        .run();
    }

    const row = tx
      .update(milestones)
      .set({ closedAt: stamp, updatedAt: stamp })
      .where(
        and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
      )
      .returning()
      .get();
    if (!row) throw new Error(`Milestone ${milestoneId} not found`);
    return { milestone: toMilestone(row), movedIssueIds: moved };
  });
}

/** Progress per milestone over live issues only. */
export async function progressByMilestone(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<ReadonlyMap<MilestoneId, MilestoneProgress>> {
  const result = new Map<MilestoneId, MilestoneProgress>();
  if (milestoneIds.length === 0) return result;

  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        inArray(issues.milestoneId, [...milestoneIds]),
        isNull(issues.archivedAt),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  const tally = new Map<string, { open: number; closed: number }>();
  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const entry = tally.get(row.milestoneId) ?? { open: 0, closed: 0 };
    if (CLOSED_ISSUE_STATUSES.includes(row.status)) entry.closed += row.value;
    else entry.open += row.value;
    tally.set(row.milestoneId, entry);
  }

  for (const id of milestoneIds) {
    const entry = tally.get(id) ?? { open: 0, closed: 0 };
    result.set(id, {
      total: entry.open + entry.closed,
      open: entry.open,
      closed: entry.closed,
    });
  }
  return result;
}
